// Generated by vibelang from src/state/commandOutput.ts; the migrate flow writes it again with each batch.
import { appendTerminalOutput, EMPTY_TERMINAL_OUTPUT, } from "@t3tools/shared/terminalOutput";
export const EMPTY_COMMAND_OUTPUT = {
    output: EMPTY_TERMINAL_OUTPUT,
    running: true,
};
/**
 * Applies one server frame. A `replace` carries the whole bounded tail (the
 * first frame, a viewer that fell behind, or the final output); an `append`
 * is raw terminal text normalized with the same rules the server uses.
 */
export function applyCommandOutputFrame(view, frame) {
    const base = frame.kind === "replace" ? EMPTY_TERMINAL_OUTPUT : view.output;
    return {
        output: appendTerminalOutput({ ...base, truncated: base.truncated || frame.truncated }, frame.text),
        running: frame.running,
    };
}
